-- Venue Live Guest "Cosplay Gathering Neon Anime". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara cosplay), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'cosplay', 'Cosplay Gathering Neon Anime (sakura)', 'cosplay', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 132, 'center 38%',
  $t${"name":"Neon Cosplay","orn":"blossom","ui":{"ivory":"#F6F0FF","white":"#FFFFFF","soft":"#E8D8FF","soft2":"#C9A6F5","accent":"#A83FD6","deep":"#3A1A70","ink":"#2B1458","mute":"#7A62A8","line":"#DCC8F7","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FBF8FF","ink":"#2B1458","accent":"#A83FD6","gold":"#F2B705","leaf":"#E8D8FF","hbg":"rgba(246,240,255,.94)","hline":"#C9A6F5","motif":"blossom"},"hud":{"bg":"rgba(43,20,88,.9)","acc":"#FF8AD1","on":"#2B1458"},"scr":{"wine":"#3A1A70","veil":"246,240,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'cosplay');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/cosplay/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/cosplay/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/cosplay/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/cosplay/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/cosplay/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/cosplay/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/cosplay/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/cosplay/arch.webp"},"fountain":{"url":"/assets/live-decor/cosplay/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/cosplay/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/cosplay/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/cosplay/table.webp"},"banner":{"url":"/assets/live-decor/cosplay/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/cosplay/gifts.webp","w":1.8},"lamp":{"url":"/assets/live-decor/cosplay/lamp.webp","w":1.3,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/cosplay/rope.webp","w":1.3,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/cosplay/planter.webp","w":1.3,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/cosplay/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/cosplay/av_host.webp","name":"Sakura Kitsune"},"av_l1":{"url":"/assets/live-decor/cosplay/av_l1.webp","name":"Kak Kuping Kucing"},"av_l2":{"url":"/assets/live-decor/cosplay/av_l2.webp","name":"Kak Samurai"},"av_l3":{"url":"/assets/live-decor/cosplay/av_l3.webp","name":"Kak Steampunk"},"av_l4":{"url":"/assets/live-decor/cosplay/av_l4.webp","name":"Kak Topeng Rubah"},"av_p1":{"url":"/assets/live-decor/cosplay/av_p1.webp","name":"Kak Hijab Kucing"},"av_p2":{"url":"/assets/live-decor/cosplay/av_p2.webp","name":"Kak Maid Biru"},"av_p3":{"url":"/assets/live-decor/cosplay/av_p3.webp","name":"Kak Hijab Kimono"}}$d$::jsonb, background_url = '/assets/live-decor/cosplay/painting.webp', active = true, updated_at = now() where key = 'cosplay';
